const wb = $('🔔 Webhook: Generar Imagen').item.json;
const body = wb.body || wb;

const post_id    = String(body.post_id || '');
const company_id = String(body.company_id || '1');
const platform   = (body.platform || 'instagram').toLowerCase();
const style      = (body.style || 'fotografía').toLowerCase();

const postsRaw = $('📋 Obtener Post G54').item.json;
const postsArr = Array.isArray(postsRaw) ? postsRaw
  : (postsRaw.data || postsRaw.posts || [postsRaw]);

const post = postsArr.find(p => String(p.id) === post_id || String(p.post_id) === post_id);
if (!post) throw new Error(`Post ${post_id} not found (total: ${postsArr.length})`);

// --- Extract post fields ---
const clientIdea = post.idea_cliente || post.client_idea || post.descripcion_imagen || '';
const hook       = post.hook || '';
const tema       = post.tema || '';
const copy       = platform === 'facebook' ? (post.copy_facebook || post.copy_instagram || '')
                 : platform === 'linkedin' ? (post.copy_linkedin || post.copy_instagram || '')
                 : (post.copy_instagram || '');

// Extract hashtags → readable keywords
const hashtagMatches = copy.match(/#[\w]+/g) || [];
const hashtagKeywords = hashtagMatches
  .map(h => h.replace('#', '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .toLowerCase()
  )
  .join(', ');

const copyNarrative = copy.replace(/#[\w]+/g, '').replace(/\n+/g, ' ').trim().slice(0, 200);

// --- Content reference (topic context) ---
let contentRef;
if (clientIdea.trim()) {
  contentRef = clientIdea.trim();
  if (hashtagKeywords) contentRef += `, ${hashtagKeywords}`;
} else {
  const parts = [];
  if (hook)            parts.push(hook);
  if (tema)            parts.push(tema);
  if (copyNarrative)   parts.push(copyNarrative);
  if (hashtagKeywords) parts.push(hashtagKeywords);
  contentRef = parts.filter(Boolean).join('. ');
}

// --- Business anchor — ALWAYS FIRST, dominates the scene ---
// Pollinations weights the beginning of the prompt most heavily.
// This forces the model to stay in the industrial crating/packaging world.
// --- Config ---
const cfg = $('⚙️ Config Pollinations').item.json;
const apiKey   = cfg.POLLINATIONS_API_KEY;
const baseUrl  = cfg.POLLINATIONS_BASE_URL;
// model: from webhook param > config default. Free models: flux, zimage, klein, nova-canvas
const model = (body.model || cfg.POLLINATIONS_DEFAULT_MODEL || 'flux').toLowerCase();

const businessAnchor = 'industrial wooden crates and packaging boxes in a Miami warehouse, wood crating company, stacked timber crates, export packaging, lumber and plywood construction';

// --- Style instructions ---
const styleMap = {
  'fotografía': 'sharp professional photograph, real-world industrial setting, natural warehouse lighting, high resolution DSLR, photorealistic, 4K, no CGI',
  'fotografia': 'sharp professional photograph, real-world industrial setting, natural warehouse lighting, high resolution DSLR, photorealistic, 4K, no CGI',
  'ilustración': 'clean flat digital illustration, vector art style, bold outlines, vibrant flat colors, professional graphic design',
  'ilustracion': 'clean flat digital illustration, vector art style, bold outlines, vibrant flat colors, professional graphic design',
  'minimalista': 'minimalist composition, clean background, single centered wooden crate or box, generous negative space, simple elegant layout',
  'corporativo': 'professional industrial photography, warehouse environment, workers in hard hats and safety vests, organized loading dock, bright clean facility',
  'vibrante':   'vivid saturated colors, dynamic diagonal composition, bold contrast, energetic visual impact, eye-catching social media style',
  'oscuro':     'dramatic dark moody lighting, deep shadows, premium dark warehouse background, metallic and wood accents, sophisticated industrial aesthetic',
};
const styleInstructions = styleMap[style] || styleMap['fotografía'];

// --- Platform composition specs (format + layout, NOT subject matter) ---
const platformAesthetic = {
  instagram: 'square 1:1 composition, centered subject, strong focal point filling 60% of frame, bold visual hierarchy, vivid balanced colors, mobile feed optimized',
  facebook:  'wide 1.91:1 landscape composition, rule of thirds layout, subject on left or right third, breathing room on edges, clear horizon line, desktop and mobile feed optimized',
  linkedin:  'wide landscape composition, clean organized layout, neutral-to-warm color palette, professional industrial tone, clear separation of foreground and background',
};
const platformSpec = platformAesthetic[platform] || platformAesthetic.instagram;

// --- Platform dimensions ---
const dims = {
  instagram: {width: 1080, height: 1080},
  facebook:  {width: 1200, height: 630},
  linkedin:  {width: 1200, height: 627},
};
const {width, height} = dims[platform] || dims.instagram;

// --- Quality & negatives ---
const textQuality = 'any text or labels must be clean, sharp, legible and properly rendered';

const negatives = [
  'no business portraits, no headshots, no stock photo people posing, no office environment',
  'no distorted text, no garbled letters, no corrupted fonts, no illegible writing',
  'no extra limbs, no deformed hands, no fused fingers, no broken anatomy',
  'no impossible angles, no floating objects without shadow, no distorted perspective',
  'no muddy textures, no inconsistent lighting direction',
  'no cropped heads, no half-cut subjects, no unintended duplicates',
  'no watermarks, no low resolution, no JPEG artifacts, no noise',
].join(', ');

// --- Final prompt ---
// Order: business scene (dominant) → content topic → platform layout → style → text quality → negatives
const prompt = [
  businessAnchor,
  contentRef.slice(0, 300),
  platformSpec,
  styleInstructions,
  textQuality,
  negatives,
].join(', ');

const promptEncoded = encodeURIComponent(prompt.slice(0, 1800));
// image.pollinations.ai is free (no auth needed). gen.pollinations.ai requires pollen balance.
const imageUrl = `${baseUrl}/${promptEncoded}?model=${model}&width=${width}&height=${height}&nologo=true&seed=${Date.now()}`;

return [{ json: {
  post_id,
  company_id,
  platform,
  style,
  model,
  client_idea_used: clientIdea ? clientIdea.slice(0, 100) : null,
  hashtags_used: hashtagKeywords.slice(0, 150),
  content_ref: contentRef.slice(0, 200),
  image_url_template: imageUrl,
  agent_token: 'g54_agent_produccion_2026'
}}];

const inp = $('🎨 Construir Prompt').item.json;
return [{ json: {
  post_id:     inp.post_id,
  company_id:  inp.company_id,
  image_url:   inp.image_url_template,
  agent_token: inp.agent_token
}}];

